material.text:
扫描命中行的代码上下文（±25 行窗口，L<n> 为包内原始行号）：
L1: /**
L2:  * 开箱即用演示 — 用内置测试数据渲染全部 4 个模板
L3:  * 用法: npm run demo
L4:  */
L5: 
L6: import { execFileSync } from "child_process";
L7: import { resolve, dirname } from "path";
L8: import { fileURLToPath } from "url";
L9: 
L10: const __dirname = dirname(fileURLToPath(import.meta.url));
L11: const RENDER = resolve(__dirname, "render.js");
L12: 
L13: const templates = [
L14:   { name: "swiss-ikb", label: "Swiss IKB（默认）" },
L15:   { name: "swiss-ikb-zebra", label: "Swiss IKB Zebra" },
L16:   { name: "bw", label: "B&W 黑白打印" },
L17:   { name: "bw-zebra", label: "B&W Zebra" },
L18: ];
L19: 
L20: console.log("==> 室内报价系统 Skill — 演示渲染");
L21: console.log("    数据来源: 内置测试数据\n");
L22: 
L23: for (const tpl of templates) {
L24:   process.stdout.write(`    ${tpl.label} ... `);
L25:   try {
L26:     execFileSync("node", [
L27:       RENDER,
L28:       "--test",
L29:       "--template", tpl.name,
L30:       "--output", `./output/demo_${tpl.name}.pdf`,
L31:     ], { stdio: ["ignore", "ignore", "pipe"] });
L32:     console.log("✓");
L33:   } catch (err) {
L34:     console.log("✗ 失败");
L35:     console.error(err.stderr?.toString() || err.message);
L36:   }
L37: }
L38: 
L39: console.log("\n==> 完成！PDF 在 output/ 目录下：");
L40: for (const tpl of templates) {
L41:   console.log(`    output/demo_${tpl.name}.pdf`);
L42: }
L43: console.log("\n    下一步: 复制飞书模板，填入自己的数据，对 AI 说 /报价");
L44:

{
  "name": "quote-generator-skill",
  "version": "0.1.0",
  "description": "全案设计报价系统 Skill — 从飞书多维表读取数据，生成 HTML 报价单，导出 PDF",
  "type": "module",
  "scripts": {
    "render": "node scripts/render.js",
    "test": "node scripts/render.js --test",
    "preview": "node scripts/render.js --test",
    "demo": "node scripts/demo.js"
  },
  "dependencies": {
    "handlebars": "^4.7.8",
    "pdf-lib": "^1.17.1",
    "playwright": "^1.45.0"
  },
  "engines": {
    "node": ">=18"
  }
}
